#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;
    long long value;

    Mod998() : value(0) {}
    Mod998(long long v) : value((v % MOD + MOD) % MOD) {}

    static long long modinv(long long a, long long m = MOD) {
        long long m0 = m, t, q;
        long long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m; a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    static long long nCr(long long n, long long r) {
        if (r > n || r < 0) return 0;
        static vector<long long> fact, invFact;
        static bool initialized = false;
        if (!initialized) {
            fact.resize(n + 1);
            invFact.resize(n + 1);
            fact[0] = 1;
            for (long long i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }
            invFact[n] = modinv(fact[n], MOD);
            for (long long i = n - 1; i >= 0; i--) {
                invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
            }
            initialized = true;
        }
        return (fact[n] * ((invFact[r] * invFact[n - r]) % MOD)) % MOD;
    }

    long long add(long long a, long long b) const {
        return (a + b) % MOD;
    }

    long long subtract(long long a, long long b) const {
        return (a - b + MOD) % MOD;
    }

    long long mult(long long a, long long b) const {
        return (a * b) % MOD;
    }

    long long smallInv(long long a) const {
        return modinv(a, MOD);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    Mod998 mod;

    // Precompute inverse of (n + m)
    long long invNPlusM = mod.smallInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i);
        p = mod.mult(p, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long e = mod.mult(numPhases, phaseSize);
        long long term = mod.mult(Mod998::nCr(n, k), e);
        if (k % 2 == 1) {
            answer = mod.add(answer, term);
        } else {
            answer = mod.subtract(answer, term);
        }
    }

    cout << answer << "\n";

    return 0;
}

